        'عَلَى النَّبِيِّ الطَّيِّبِ المُمَجَّدِ'),
    Verse('مُحَمَّدٍ وَآلِهِ الأطْهَارِ',
        'وَصَحْبِهِ السَّادَاتِ وَالأبْرَارِ'),
    Verse('أبْدَأُ فِي نَظْمٍ بَدِيعٍ شَافِي',
        'لِطَالِبِ السِّيرَةِ فَهُوَ وَافِي'),
    Verse('سَمَيتُها المَنظُومَةَ اللَّطِيفَةْ',
        'في السِّيرَةِ النَّبَوِيَّةِ الشَّرِيفَةْ'),
    Verse('أبْدَأُ بَعدَ ذَاكَ بِالمِيلَادِ',
        'لِلسَّيِّدِ المُطَهَّرِ الأجْدَادِ'),
    Verse('مِنْ آدَمَ وَالنُّورُ فِي الأصْلَابِ',
        'يَسرِي بِفَضْلِ الوَاحِدِ الوَهَّابِ'),
    Verse('حَتَّى استَقَرَّ عِندَ عَبدِ اللهِ',
        'وَبِنتِ وَهْبٍ فِي كَمَالٍ بَاهِي'),
    Verse('فَجَاءَ لِلأكْوَانِ مِنْ خَيرِ أبِ',
        'وَخَيرِ أُمٍّ شَرُفَتْ فِي النَّسَبِ'),
    Verse('مَاتَ أبُوهُ قَبلَ أنْ يَرَاهُ',
        'وَجَدُّهُ مِنْ بَعدِهِ رَعَاهُ'),
    Verse('وُلِدَ فِي مَكَّةَ عَامَ الفِيلِ',
        'مِنْ بَعدِهَا بِزَمَنٍ قَلِيلِ'),
    Verse('وَعِندَهَا قَدْ جَاءَتِ الآيَاتُ',
        'فِي المَولِدِ الشَّرِيفِ بُشْرَيَاتُ'),
    Verse('قَدْ خَصَّهُ الرَّحمَنُ بِالتَّفضِيلِ',
        'فَخُذْ لِهَذَا الشَّرحِ وَالتَّفصِيلِ'),
    Verse('قُصُورُ بُصرَى صُدِّعَتْ بِالشَّامِ',
        'فِي ذَلِكَ اليَومِ عَلَى التَّمَامِ'),
    Verse('وَخَمَدَتْ فِي الفُرسِ نَارُ كِسرَى',
        'مُعجِزَةً حَتمًا لِمَنْ كَانَ يَرَى'),
    Verse('آيَاتُ هَذَا المَولِدِ الشَّرِيفِ',
        'تَوَاتَرَتْ بِالجَمعِ وَالتَّصنِيفِ'),
    Verse('وَقَدْ أتَى لِكَوْنِنَا مَختُونًا',
        'مُسَبِّحًا بِكَفِّهِ مَيمُونًا'),
    Verse('وَأرْضَعَتهُ أُمُّهُ حَلِيمَةُ',
        'ذَاتُ الوَفَاءِ السَّيِّدَةْ الكَرِيمَةُ'),
    Verse('وَشُقَّ صَدرُهُ كَمَا أتَانَا',
        'أكْرِمْ بِصَدرٍ قَدْ وَعَى القُرْآنَا'),
    Verse('وَعِندَهَا عَادَتْ بِهِ حَلِيمَةُ',
        'لِبِنتِ وَهْبٍ أُمِّهِ العَظِيمَةِ'),
    Verse('خَوفًا عَلَيهِ عِندَ شَقِّ صَدرِهِ',
        'مُؤمِنَةً بِشَأنِهِ وَقَدرِهِ'),
    Verse('وَبَعدَ سِتٍّ مِنْ سِنِينَ عُمرِهِ',
        'الأُمُّ مَاتَتْ مِنْ كَمَالِ صَبرِهِ'),
    Verse('وَبَعدَهَا جَدُّهُ عَبدُ المُطَّلِبْ',
        'بِسَنَتَينِ مِثلِهَا أيْضًا ذَهَبْ'),
    Verse('وَعَمُّهُ أخُو أبِيهِ بَعدَهُ',
        'رَعَاهُ حُبًّا وَأطَاعَ جَدَّهُ'),
    Verse('وَبَعدَهَا سَافَرَ لِلتِّجَارَةِ',
        'فِي الشَّامِ ثُمَّ عَادَ بِالبِشَارَةِ'),
    Verse('وَعِندَمَا أتَمَّ مُصطَفَانَا',
        'خَمسًا وَعِشرِينَ كَمَا أتَانَا'),
    Verse('تَزَوَّجَ السَّيِّدَةَ الكَرِيمَةْ',
        'خَدِيجَةَ الحَبِيبَةَ العَظِيمَةْ'),
    Verse('فَقَدْ أحَبَّتهُ بِصِدقٍ وَسَعَتْ',
        'فِي ذَلِكَ التَّزوِيجِ حَتَّى غَنِمَتْ'),
    Verse('كَانَتْ تَقُومُ دَائِمًا لِخِدمَتِهْ',
        'بِنَفسِهَا وَمَالِهَا لِنُصرَتِهْ'),
    Verse('فَنَالَتِ المَكَانَةَ المُعَظَّمَةْ',
        'فِي قَلبِهِ وَلَمْ تَزَلْ مُكَرَّمَةْ'),
    Verse('وَأنجَبَتْ لأحْمَدَ البَنِينَا',
        'مَعَ البَنَاتِ نُورُهُمْ مُبِينَا'),
    Verse('وَبَعدَ خَمسٍ مَعَ ثَلَاثِينَ أتَى',
        'بِنَاءُ كَعبَةٍ كَمَا قَدْ ثَبَتَا'),
    Verse('وَوَضَعَ الأَمِينُ ذَلِكَ الحَجَرْ',
        'وَعَمَّتِ الأفرَاحُ مَا بَينَ البَشَرْ'),
    Verse('فَقَدْ كَفَاهُم نِقمَةَ التَّنَازُعِ',
        'بِوَضعِهِ أكْرِمْ بِهِ مِنْ شَافِعِ'),
    Verse('وَبَعدَ ذَاكَ جَاءَهُ الرَّسُولُ',
        'مِنَ الإلَهِ مُنَزَّلًا جِبرِيلُ'),
    Verse('فِي عَامِ أربَعِينَ مِنْ سِنِينِهِ',
        'بِالوَحيِ مِنْ رَبِّي إلَى أمِينِهِ'),
    Verse('قَالَ لَهُ اقْرَأْ عِندَمَا أتَاهُ',
        'بِغَارِ حِرَاءَ وَقَدْ رَآهُ'),
    Verse('بِاسمِ الكَرِيمِ الوَاحِدِ الَّذِي خَلَقْ',
        'كَمَا أتَى فِي سُورَةٍ هِيَ العَلَقْ'),
    Verse('وَعَادَ نَحوَ بَيتِهِ عَلَيهِ مِنْ',
        'نُورِ التَّجَلِّي وَالهَدى لِيَطمَئِنَّ'),
    Verse('فَقَالَ زَمِّلُونِي زَمِّلُونِي',
        'مُنَادِيًا لِلزَّوجَةِ الحَنُونِ'),
    Verse('فَذَهَبَتْ بِهِ إلَى ابنِ عَمِّهَا',
        'وَكَانَ مِنْ أهلِ العُلُومِ وَالنُّهَى'),
    Verse('بَشَّرَهُ بِأنَّهُ رَسُولُ',
        'وَأنَّ مَنْ أتاهُ ذا جِبرِيلُ'),
    Verse('وَأنَّ هَذَا الوَحيَ كَانَ يَنزِلُ',
        'عَلَى نَبِيِّ اللهِ مُوسَى الأوَّلُ'),
    Verse('وَأنَّ قَومَهُ سَيُخرِجُونَهُ',
        'وَعَنْ بِلَادِهِ سَيَمنَعُونَهُ'),
    Verse('وَقَدْ تَمَنَّى أنْ يَكُونَ حَاضِرًا',
        'حَتَّى يَكُونَ لِلنَّبِيِّ نَاصِرًا'),
    Verse('وَبَعدَهَا دَعَى إلَى التَّوحِيدِ',
        'فِي السِّرِّ لِلأهلِ وَلِلعَبِيدِ'),
    Verse('فَآمَنَتْ بِدِينِهِ جَمَاعَةْ',
        'وَصَدَّقُوا وَأخلَصُوا اتِّبَاعَهْ'),
    Verse('مِنهُم أبُو بَكرٍ هُوَ الصِّدِّيقُ',
        'فَهُوَ الحَبِيبُ وَهُوَ الرَّفِيقُ'),
    Verse('وَمِنهُمُ خَدِيجَةُ الكَرِيمَةُ',
        'الزَّوجَةُ الشَّرِيفَةُ العَلِيمَةُ'),
    Verse('وَمِنهُمُ عَلِيٌّ الكَرَّارُ',
        'وَغَيرُهُم أصْحَابُهُ الأطْهَارُ'),
    Verse('السَّابِقُونَ الأوَّلُونَ نَعتُهُمْ',
        'فِي الذِّكرِ وَالرَّحمَنُ أعْلَى قَدرَهُم'),
    Verse('وَجَاءَ إذْنُ الدَّعوَةِ الجَهرِيَّةِ',
        'بَعدَ سِنِينَ الدَّعوَةِ السِّرِّيَّةِ'),
    Verse('فَوَقَفَ النَّبِيُّ فَوقَ الجَبَلِ',
        'مُنَادِيًا فِي قَومِهِ بِالأمَلِ'),
    Verse('مَاذَا تَرَوْنِي فِيكُمُ أجِيبُوا',
        'قَالُوا صَدُوقٌ طَاهِرٌ حَبِيبُ'),
    Verse('قَالَ لَهُمْ لَو أنَّنِي أخبَرتُكُم',
        'أنَّ العَدُوَّ خَلفَ هَذَا جَاءَكُم'),
    Verse('أكُنتُمُ مُصَدِّقِينَ قَولِي',
        'قَالُوا نَعَمْ أنتَ الصدوقُ والوَلِي'),
    Verse('قَالَ لَهُم إنِّي رَسُولُ اللهِ',
        'إلَيكُمُ تَجَنَّبُوا المَنَاهِي'),
    Verse('وَاخْلِصُوهُ وَحدَهُ العِبَادَةْ',
        'وَلِتَنطِقُوا بِكَلِمَةِ الشَّهَادَةْ'),
    Verse('فَعَانَدُوهُ عِندَهَا وَخَالَفُوا',
        'صَارُوا عَلَى عَدَائِهِ تَحَالَفُوا'),
    Verse('وَعَذَّبُوا أصْحَابَهُ تَعذِيبا',
        'وَكَذَّبُوا بِقَولِهِ تَكذِيبا'),
    Verse('وَهَاجَرَ الأصْحَابُ لِلنَّجَاشِي',
        'حَيثُ الأمَانُ وَالوَفَاءُ فَاشِي'),
    Verse('وَقَاطَعَتْ قُرَيشُ آلَ المُصطَفَى',
        'فِي الشِّعبِ حَيثُ كَابَدُوا فِيهِ الجَفَا'),
    Verse('حَتَّى انتَهَى بِقُدرَةِ الإلَهِ',
        'وَقَرَّ فِي الصَّحِيفَةِ اسمُ اللهِ'),
    Verse('وَأسلَمَ الحَمزَةُ وَالفَارُوقُ',
        'فَكَانَ نَصرًا ظَاهِرًا يَفُوقُ'),
    Verse('وَأظهَرَ الصَّحَابَةُ الإيمَانَا',
        'مِنْ بَعدِ ذَا وَأعلَنُوا إعلَانَا'),
    Verse('وَمَاتَ عَمُّ المُصطَفَى وَزَوجَتُهُ',
        'وَذَاكَ عَامُ الحُزنِ حَيثُ شِدَّتُهُ'),
    Verse('وَسَارَ لِلطَّائِفِ يَدعُوهُمْ إلَى',
        'رِضَا الكَرِيمِ مِثلَ مَا قَدْ أُرسِلَا'),
    Verse('فَأطلَقُوا السُّفَهَاءَ بِالإيذَاءِ',
        'لِسَيِّدِ السَّادَاتِ فِي جَفَاءِ'),
    Verse('وَحِينَ ذَاكَ جَاءَهُ المَلَكَانِ',
        'لِيَطلُبَا الهَلَاكَ لِلمَكَانِ'),
    Verse('أجَابَهُمْ بِعَفوِهِ رَحِيما',
        'فَقَدْ نَشَا عَلَى العَطَا كَرِيما'),
    Verse('وَبَعدَهَا حَادِثَةُ المِعرَاجِ',
        'وَبَعدَهَا قَبَائِلُ الحُجَّاجِ'),
    Verse('جَاءُوا لِمَكَّةَ وَصَدَّقُوهُ',
        'مِنْ أهلِ طَيبَةَ وَبَايَعُوهُ'),
    Verse('وَبَعدَهَا قَدْ جَاءَ إذْنُ الهِجرَةِ',
        'لِطَيبَةَ بِالبِشرِ وَالمَسَرَّةِ'),
    Verse('فَهَاجَرَ الأصْحَابُ أوَّلًا إلَى',
        'مَدِينَةِ الأنْوَارِ أرضِ النُّبَلَا'),
    Verse('وَانطَلَقَ النَّبِيُّ وَالصِّدِّيقُ',
        'لِغَارِ ثَورٍ مَعْهُمَا رَفِيقُ'),
    Verse('يَدُلُّهُمْ إلَى الطَّرِيقِ إنَّهُ',
        'ابنُ أرِيقِطَ وَذَاكَ فَنُّهُ'),
    Verse('وَقَدْ أتَى لِلغَارِ أهلُ الكُفرِ',
        'لِيَقتُلُوا الَّذِي أتَى بِالذِّكرِ'),
    Verse('فَلَمْ يَرَوْهُ أُغشِيَتْ أبصَارُهُم',
        'وَالعَنكَبُوتُ أُنسِجَتْ أمَامَهُم'),
    Verse('وَبَاضَتِ الحَمَامُ عِندَ الغَارِ',
        'مَحَبَّةً فِي سَيِّدِ الأبرَارِ'),
    Verse('نَجَا بِعَونِ اللهِ مِنْ أذَاهُم',
        'وَسَارَ لِلأنصَارِ قَدْ هَوَاهُم'),
    Verse('وَوَدَّعَ النَّبِيُّ أرضَهُ مَعَا',
        'بُكَاءِه وَالعَينُ فَاضَتْ أدْمُعَا'),
    Verse('فَقَدْ أحَبَّهَا بِغَيرِ حَدِّ',
        'وَلَمْ يَكُنْ يُطِيقُ أيَّ بُعدِ'),
    Verse('وَفِي الطَّرِيقِ قَدْ رَأى سُرَاقَةْ',
        'نَبِيَّنَا وَنَفسُهُ تَوَّاقَةْ'),
    Verse('أنْ يَأخُذَ الأمْوَالَ وَالجِمَالَا',
        'مُسَارِعًا إلَيهِمُ إقبَالَا'),
    Verse('فَغَاصَ مِنهُ خَيلُهُ فِي الرَّملِ',
        'دَعَا لَهُ إمَامُ أهلِ الفَضلِ'),
    Verse('فَجَاءَ نَحوَ المُصطَفَى مُسَـلِّما',
        'عَلَيهِ فأجَابَهُ مُكَلِّما'),
    Verse('بِوعَدِهِ بِتَركِهِم سِوَارِي',
        'كِسرَى بِغَيرِ شَكٍّ فِي الحِوَارِ'),
    Verse('فَعَادَ نَحوَ قَومِهِ أمِينا',
        'مُنَافِحًا لأجْلِهِ مُعِينا'),
    Verse('وَبَعدَهَا أتَوا لأُمِّ مَعبَدِ',
        'مَنْ وَصَفَتْ لِسَيِّدِي المُمَجَّدِ'),
    Verse('فَلَمْ يَكُنْ لَدَيهَا غَيرُ شَاةِ',
        'عَاجِزَةٍ مَلَّتْ مِنَ الحَيَاةِ'),
    Verse('دَعَا بِهَا المُختَارُ ثُمَّ مَسَّهَا',
        'بِكَفِّهِ فَأنزَلَتْ حَلِيبَهَا'),
    Verse('فَشَرِبُوا جَمِيعُهُم وَشَبِعُوا',
        'وَفِي المَسِيرِ بَعدَ ذَاكَ شَرَعُوا'),
    Verse('وَعَادَ زَوجُهَا فَكَانَ مُعجَبا',
        'بِمَا رَأى مِنْ شَاتِهِ تَعَجُّبا'),
    Verse('فَوَصَفَتْهُ خَيرَ وَصفٍ كَانَا',
        'وَعَمَّرَتْ أوصَافُهَا الزَّمَانَا'),
    Verse('لَهَا كَلَامٌ فِيهِ لَا مَثِيلَ لَهْ',
        'وَوَصفُهَا فِي المُصطَفَى مَا أجمَلَهْ'),
    Verse('وَأهلُ طَيبَةَ عَلَى الأبوَابِ',
        'يَنتَظِرُونَ سَيِّدَ الأحبَابِ'),
    Verse('فَجَاءَهُم نَبِيُّنَا المُختَارْ',
        'وَكُلُّهُم يَهتِفُ بِالأشعَارْ'),
    Verse('أضَاءَ مِنهَا كُلُّ شَيءٍ عِندَمَا',
        'دَخَلَهَا المُختَارُ وَالخَيرُ نَمَا'),
    Verse('وَأنشَأَ المَسجِدَ لِلصَّلَاةِ',
        'وَالدَّعوَةِ الكُبرَى وَلِلحَيَاةِ'),
    Verse('قَدِ انتَهَى بِفَضلِهِ الخِصَامُ',
        'مِنْ بَينِهِم وَالكُرهُ وَالظَّلَامُ'),
    Verse('وَشَاعَ مِنْ بَينِهِمُ الوِئَامُ',
        'وَالحُبُّ وَالوِدَادُ وَالسَّلَامُ'),
    Verse('فَأصبَحُوا بِفَضلِهِ جَمِيعا',
        'حِصنًا عَلَى أعْدَائِهِم مَنِيعا'),
    Verse('آخَىٰ النَّبِيُّ بَينَ مَنْ قَدْ هَاجَرَا',
