        'وَسَائِلُ الأَطْرَافِ ذُو فَصَاحَةْ'),
    Verse('وَمَشْيُهُ هَوْنًا مَسِيحُ القَدَمَيْنْ',
        'يَنْبُو عَنْهُمَا المَا خُمْصَانُ الأَخْمَصَيْنْ'),
    Verse('وَخَافِضُ الطَّرْفِ نَظَرُهُ إِلَى',
        'أَرْضٍ مِنَ السَّمَاءِ دَوْمًا أَطْوَلَا'),
    Verse('بَيْنَ كَتِفَيْهِ خَاتَمُ النُّبُوءَةْ',
        'وَقَدْ أَتَى بِالنُّورِ وَالمُرُوءَةْ'),
    Verse('تَمَّتْ بِفَضْلِ الْوَاحِدِ الْوَهَّابِ',
        'أَلْفِيَّةً عَنْ سَيِّدِ الْأَحْبَابِ'),
    Verse('الْمُصْطَفَى الْهَادِي إِلَى الرَّشَادِ',
        'الطَّاهِرِ الْآبَاءِ وَالْأَجْدَادِ'),
    Verse('صَلَّى عَلَيْهِ رَبُّنَا وَسَلَّمَا',
        'وَآلِهِ وَصَحْبِهِ وَكَرَّمَا'),
    Verse('تَحْكِي لَنَا سِيرَتَهُ الشَّرِيفَةْ',
        'مُيَسُورَةً أَلْفَاظُهَا لَطِيفَةْ'),
    Verse('وَالْحَمْدُ لِلَّهِ عَلَى الدَّوَامِ',
        'وَالشُّكْرُ لِلرَّحْمَنِ فِي الْخِتَامِ'),
  ]),
];
